import XCTest
import Foundation
@testable import MacVisio

final class VisioFormatTests: XCTestCase {
    private let namespace = "http://schemas.microsoft.com/office/visio/2011/1/core"
    private let relNamespace = "http://schemas.openxmlformats.org/package/2006/relationships"
    private let visioRel = "http://schemas.microsoft.com/visio/2010/relationships/"

    // The rectangle ShapeSheet values and geometry below are the independent
    // Microsoft MS-VSDX 3.1.3 example, not generated by our exporter.
    // https://learn.microsoft.com/en-us/openspecs/sharepoint_protocols/ms-vsdx/dccbb4b5-ca0c-43ef-9379-00c1acb54377
    private let exampleRectangle = """
    <Shape ID="1" Type="Shape" LineStyle="0" FillStyle="0" TextStyle="0">
      <Cell N="PinX" V="4"/><Cell N="PinY" V="5.5"/>
      <Cell N="Width" V="2"/><Cell N="Height" V="1"/>
      <Cell N="LocPinX" V="1"/><Cell N="LocPinY" V="0.5"/>
      <Cell N="Angle" V="0"/><Cell N="FillForegnd" V="#0070c0"/>
      <Section N="Geometry" IX="0">
        <Row T="RelMoveTo" IX="1"><Cell N="X" V="0"/><Cell N="Y" V="0"/></Row>
        <Row T="RelLineTo" IX="2"><Cell N="X" V="1"/><Cell N="Y" V="0"/></Row>
        <Row T="RelLineTo" IX="3"><Cell N="X" V="1"/><Cell N="Y" V="1"/></Row>
        <Row T="RelLineTo" IX="4"><Cell N="X" V="0"/><Cell N="Y" V="1"/></Row>
        <Row T="RelLineTo" IX="5"><Cell N="X" V="0"/><Cell N="Y" V="0"/></Row>
      </Section><Text>Sample text</Text>
    </Shape>
    """

    func testImportsIndependentMicrosoftRectangleExample() throws {
        let url = try fixture(shapes: exampleRectangle)
        let result = try VisioFormat.read(from: url)
        XCTAssertEqual(result.diagram.pages.count, 1)
        let page = result.diagram.page
        XCTAssertEqual(page.width, 612, accuracy: 0.0001)
        XCTAssertEqual(page.height, 792, accuracy: 0.0001)
        let node = try XCTUnwrap(page.nodes.first)
        XCTAssertEqual(node.kind, .rectangle)
        XCTAssertEqual(node.x, 216, accuracy: 0.0001)
        XCTAssertEqual(node.y, 360, accuracy: 0.0001)
        XCTAssertEqual(node.width, 144, accuracy: 0.0001)
        XCTAssertEqual(node.height, 72, accuracy: 0.0001)
        XCTAssertEqual(node.fill, "#0070C0")
        XCTAssertEqual(node.text, "Sample text")
        XCTAssertEqual(node.stroke, "#336699")
        XCTAssertEqual(node.fontSize, 18, accuracy: 0.0001)
        XCTAssertTrue(result.warnings.contains(where: { $0.contains("cached values") }))
    }

    func testMasterInheritanceAndOwnOverrides() throws {
        let masterShape = exampleRectangle.replacingOccurrences(of: "Sample text", with: "Master label")
        let shapes = "<Shape ID=\"5\" Type=\"Shape\" Master=\"7\"><Cell N=\"PinX\" V=\"3\"/><Cell N=\"PinY\" V=\"4\"/><Cell N=\"FillForegnd\" V=\"#FFEEDD\"/><Text>Own <cp IX=\"0\"/>label &amp; text</Text></Shape>"
        var extra = [String: String]()
        extra["visio/masters/masters.xml"] = "<Masters xmlns=\"\(namespace)\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><Master ID=\"7\" NameU=\"Decision\"><Rel r:id=\"rId1\"/></Master></Masters>"
        extra["visio/masters/_rels/masters.xml.rels"] = rels([("rId1", "master", "master1.xml")])
        extra["visio/masters/master1.xml"] = "<MasterContents xmlns=\"\(namespace)\"><Shapes>\(masterShape)</Shapes></MasterContents>"
        let url = try fixture(shapes: shapes, extra: extra, documentRelations: [("rId2", "masters", "masters/masters.xml")])
        let node = try XCTUnwrap(VisioFormat.read(from: url).diagram.page.nodes.first)
        XCTAssertEqual(node.kind, .diamond)
        XCTAssertEqual(node.width, 144)
        XCTAssertEqual(node.x, 144)
        XCTAssertEqual(node.y, 468)
        XCTAssertEqual(node.fill, "#FFEEDD")
        XCTAssertEqual(node.stroke, "#336699")
        XCTAssertEqual(node.text, "Own label & text")
    }

    func testPublicConnectRecordsAttachConnectorToCorrectShapes() throws {
        let second = exampleRectangle.replacingOccurrences(of: "ID=\"1\"", with: "ID=\"2\"").replacingOccurrences(of: "N=\"PinX\" V=\"4\"", with: "N=\"PinX\" V=\"7\"")
        let connector = """
        <Shape ID="3" Type="Shape" LineStyle="0"><Cell N="BeginX" V="5"/><Cell N="BeginY" V="5.5"/><Cell N="EndX" V="6"/><Cell N="EndY" V="5.5"/><Cell N="EndArrow" V="4"/><Text>Yes</Text></Shape>
        """
        let connects = "<Connect FromSheet=\"3\" FromCell=\"BeginX\" ToSheet=\"1\" ToCell=\"PinX\"/><Connect FromSheet=\"3\" FromCell=\"EndX\" ToSheet=\"2\" ToCell=\"PinX\"/>"
        let url = try fixture(shapes: exampleRectangle + second + connector, connects: connects)
        let result = try VisioFormat.read(from: url)
        XCTAssertEqual(result.diagram.page.nodes.count, 2)
        let edge = try XCTUnwrap(result.diagram.page.edges.first)
        XCTAssertEqual(edge.source, result.diagram.page.nodes[0].id)
        XCTAssertEqual(edge.target, result.diagram.page.nodes[1].id)
        XCTAssertEqual(edge.label, "Yes")
        XCTAssertTrue(edge.arrow)
        XCTAssertEqual(edge.color, "#336699")
        XCTAssertEqual(edge.width, 1.5, accuracy: 0.0001)
        XCTAssertEqual(edge.style, .straight)
    }

    func testExactNativeRoundTripIncludingEveryShapeAndSecondPage() throws {
        var diagram = Diagram()
        diagram.title = "Workflow <A> & review"
        diagram.page.nodes = ShapeKind.allCases.enumerated().map { index, kind in
            var node = DiagramNode(kind: kind, x: Double(index * 40), y: Double(index * 20), text: "A & B \"quoted\"\n第二行")
            node.rotation = Double(index * 7); node.bold = index.isMultiple(of: 2); node.locked = index == 1
            return node
        }
        var edge = DiagramEdge(source: diagram.page.nodes[0].id, target: diagram.page.nodes[1].id)
        edge.label = "Next & continue"; edge.style = .straight
        diagram.page.edges = [edge]
        var second = DiagramPage(); second.name = "Review"
        second.nodes = [DiagramNode(kind: .diamond, x: 20, y: 40)]
        diagram.pages.append(second); diagram.activePageID = second.id
        let url = temporaryURL("own.vsdx")
        try VisioFormat.write(diagram, to: url)
        let result = try VisioFormat.read(from: url)
        var content = result.diagram; content.visioArchive = nil
        XCTAssertEqual(content, diagram)
        XCTAssertTrue(result.warnings.isEmpty)
        let contents = try readPart(url, "visio/pages/page1.xml")
        XCTAssertTrue(contents.contains("RelCubBezTo"))
        XCTAssertTrue(contents.contains("<Connect FromSheet="))
        XCTAssertTrue(contents.contains("&amp;"))
        XCTAssertTrue(contents.contains("<Section N=\"Character\""))
        let document = try readPart(url, "visio/document.xml")
        XCTAssertTrue(document.contains("<VisioDocument"))
        let contentTypes = try readPart(url, "[Content_Types].xml")
        XCTAssertTrue(contentTypes.contains("application/vnd.ms-visio.drawing.main+xml"))
        XCTAssertTrue(contentTypes.contains("/visio/pages/page2.xml"))
    }

    func testExportPublicPartsWorkWithoutMacVisioMetadata() throws {
        var diagram = Diagram()
        var first = DiagramNode(kind: .diamond, x: 140, y: 200, text: "Review?")
        first.width = 123; first.height = 91; first.rotation = 24; first.fontSize = 16; first.bold = true
        let second = DiagramNode(kind: .ellipse, x: 360, y: 210, text: "Done")
        diagram.page.nodes = [first, second]
        diagram.page.edges = [DiagramEdge(source: first.id, target: second.id)]
        let url = temporaryURL("public.vsdx")
        try VisioFormat.write(diagram, to: url)
        try process("/usr/bin/zip", ["-qd", url.path, "macvisio/document.json"])
        let imported = try VisioFormat.read(from: url).diagram
        XCTAssertEqual(imported.page.nodes.map(\.kind), [.diamond, .ellipse])
        XCTAssertEqual(imported.page.nodes[0].x, 140, accuracy: 0.0001)
        XCTAssertEqual(imported.page.nodes[0].y, 200, accuracy: 0.0001)
        XCTAssertEqual(imported.page.nodes[0].width, 123, accuracy: 0.0001)
        XCTAssertEqual(imported.page.nodes[0].height, 91, accuracy: 0.0001)
        XCTAssertEqual(imported.page.nodes[0].rotation, 24, accuracy: 0.0001)
        XCTAssertEqual(imported.page.nodes[0].fontSize, 16, accuracy: 0.0001)
        XCTAssertTrue(imported.page.nodes[0].bold)
        XCTAssertEqual(imported.page.edges.count, 1)
        XCTAssertEqual(imported.page.edges[0].source, imported.page.nodes[0].id)
        XCTAssertEqual(imported.page.edges[0].target, imported.page.nodes[1].id)
    }

    func testVisioEditsInvalidatePrivateMetadata() throws {
        var diagram = Diagram()
        diagram.page.nodes = [DiagramNode(text: "Original")]
        let url = temporaryURL("edited.vsdx")
        try VisioFormat.write(diagram, to: url)
        let originalPage = try readPart(url, "visio/pages/page1.xml")
        let replacementPage = originalPage.replacingOccurrences(of: "<Text>Original</Text>", with: "<Text>Edited in Visio</Text>")
        let directory = temporaryDirectory()
        let file = directory.appendingPathComponent("visio/pages/page1.xml")
        try FileManager.default.createDirectory(at: file.deletingLastPathComponent(), withIntermediateDirectories: true)
        try Data(replacementPage.utf8).write(to: file)
        try process("/usr/bin/zip", ["-q", url.path, "visio/pages/page1.xml"], directory: directory)
        let result = try VisioFormat.read(from: url)
        XCTAssertEqual(result.diagram.page.nodes.first?.text, "Edited in Visio")
        XCTAssertTrue(result.warnings.contains(where: { $0.contains("changed outside MacVisio") }))
    }

    func testRejectsDTDAndEntityDeclarations() throws {
        let url = try fixture(shapes: exampleRectangle, pagePrefix: "<!DOCTYPE PageContents [<!ENTITY attack SYSTEM 'file:///etc/passwd'>]>")
        XCTAssertThrowsError(try VisioFormat.read(from: url)) { error in
            XCTAssertTrue(error.localizedDescription.contains("DTD"))
        }
    }

    func testRejectsRelationshipsEscapingPackageAndMalformedGeometry() throws {
        let escaping = try fixture(shapes: exampleRectangle, pageTarget: "../../../outside.xml")
        XCTAssertThrowsError(try VisioFormat.read(from: escaping))
        let nonfinite = try fixture(shapes: exampleRectangle.replacingOccurrences(of: "N=\"Width\" V=\"2\"", with: "N=\"Width\" V=\"NaN\""))
        XCTAssertThrowsError(try VisioFormat.read(from: nonfinite))
        let duplicate = try fixture(shapes: exampleRectangle + exampleRectangle)
        XCTAssertThrowsError(try VisioFormat.read(from: duplicate))
        let malformed = try fixture(shapes: "<Shape ID=\"1\"><Cell></Shape>")
        XCTAssertThrowsError(try VisioFormat.read(from: malformed))
    }

    func testHighlyCompressedOversizedPartIsBounded() throws {
        let url = try fixture(shapes: "<Shape ID=\"1\"><Text>" + String(repeating: "A", count: 16 * 1024 * 1024) + "</Text></Shape>")
        XCTAssertThrowsError(try VisioFormat.read(from: url)) { error in
            XCTAssertTrue(error.localizedDescription.contains("size limit"))
        }
    }

    func testGroupsAndUnattachedLinesAreImported() throws {
        let group = "<Shape ID=\"4\" Type=\"Group\"><Cell N=\"Width\" V=\"2\"/><Cell N=\"Height\" V=\"1\"/><Shapes>\(exampleRectangle)</Shapes></Shape>"
        let line = "<Shape ID=\"5\"><Cell N=\"BeginX\" V=\"0\"/><Cell N=\"EndX\" V=\"1\"/></Shape>"
        let url = try fixture(shapes: group + line)
        let result = try VisioFormat.read(from: url)
        XCTAssertEqual(result.diagram.page.nodes.count, 2)
        XCTAssertTrue(result.diagram.page.nodes[0].formatting.isGroup)
        XCTAssertEqual(result.diagram.page.nodes[1].parentID,result.diagram.page.nodes[0].id)
        XCTAssertEqual(result.diagram.page.edges.count,1)
        XCTAssertNotNil(result.diagram.page.edges[0].sourcePosition)
    }

    private func fixture(shapes: String, connects: String = "", extra: [String: String] = [:], documentRelations: [(String, String, String)] = [], pagePrefix: String = "", pageTarget: String = "page1.xml") throws -> URL {
        var parts: [String: String] = [:]
        parts["[Content_Types].xml"] = "<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/visio/document.xml\" ContentType=\"application/vnd.ms-visio.drawing.main+xml\"/></Types>"
        parts["_rels/.rels"] = rels([("rId1", "document", "visio/document.xml")])
        parts["visio/document.xml"] = "<VisioDocument xmlns=\"\(namespace)\"><StyleSheets><StyleSheet ID=\"0\"><Cell N=\"LineColor\" V=\"#336699\"/><Cell N=\"LineWeight\" V=\"0.0208333333333333\"/><Section N=\"Character\"><Row IX=\"0\"><Cell N=\"Size\" V=\"0.25\"/><Cell N=\"Color\" V=\"#112233\"/></Row></Section></StyleSheet></StyleSheets></VisioDocument>"
        parts["visio/_rels/document.xml.rels"] = rels([("rId1", "pages", "pages/pages.xml")] + documentRelations)
        parts["visio/pages/pages.xml"] = "<Pages xmlns=\"\(namespace)\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><Page ID=\"0\" Name=\"Example\"><PageSheet><Cell N=\"PageWidth\" V=\"8.5\"/><Cell N=\"PageHeight\" V=\"11\"/></PageSheet><Rel r:id=\"rId1\"/></Page></Pages>"
        parts["visio/pages/_rels/pages.xml.rels"] = rels([("rId1", "page", pageTarget)])
        parts["visio/pages/page1.xml"] = pagePrefix + "<PageContents xmlns=\"\(namespace)\"><Shapes>\(shapes)</Shapes><Connects>\(connects)</Connects></PageContents>"
        parts.merge(extra) { _, new in new }
        let directory = temporaryDirectory()
        for (path, value) in parts {
            let url = directory.appendingPathComponent(path)
            try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
            try Data(value.utf8).write(to: url)
        }
        let output = directory.appendingPathComponent("fixture.vsdx")
        try process("/usr/bin/zip", ["-q", output.path] + parts.keys.sorted(), directory: directory)
        return output
    }

    private func rels(_ values: [(String, String, String)]) -> String {
        "<Relationships xmlns=\"\(relNamespace)\">" + values.map { "<Relationship Id=\"\($0.0)\" Type=\"\(visioRel)\($0.1)\" Target=\"\($0.2)\"/>" }.joined() + "</Relationships>"
    }
    private func temporaryDirectory() -> URL {
        let url = FileManager.default.temporaryDirectory.appendingPathComponent("MacVisioTests-\(UUID().uuidString)", isDirectory: true)
        try! FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
        addTeardownBlock { try? FileManager.default.removeItem(at: url) }
        return url
    }
    private func temporaryURL(_ name: String) -> URL { temporaryDirectory().appendingPathComponent(name) }
    @discardableResult private func process(_ path: String, _ arguments: [String], directory: URL? = nil) throws -> Data {
        let process = Process(), pipe = Pipe()
        process.executableURL = URL(fileURLWithPath: path); process.arguments = arguments
        process.currentDirectoryURL = directory; process.standardOutput = pipe; process.standardError = FileHandle.nullDevice
        try process.run()
        let data = pipe.fileHandleForReading.readDataToEndOfFile()
        process.waitUntilExit()
        guard process.terminationStatus == 0 else { throw DiagramError.invalid("Fixture archive operation failed.") }
        return data
    }
    private func readPart(_ url: URL, _ name: String) throws -> String {
        let escaped = name.replacingOccurrences(of: "[", with: "\\[").replacingOccurrences(of: "]", with: "\\]")
        return String(decoding: try process("/usr/bin/unzip", ["-p", url.path, escaped]), as: UTF8.self)
    }
}
